#include "Studio.h"
#include "ControlEdits.h"
#include <cmath>
namespace pulse {
using namespace juce;
namespace {
var object(){return var(new DynamicObject());}
bool numeric(const var& v,double low,double high,bool integer=false){if(!(v.isInt()||v.isInt64()||v.isDouble()))return false;double n=(double)v;return std::isfinite(n)&&n>=low&&n<=high&&(!integer||n==std::floor(n));}
bool safeName(const var& v){auto s=v.toString();return v.isString()&&s.length()>0&&s.length()<=80&&s[0]!=' '&&s==s.trim()&&s.containsOnly("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 _-");}
}
Result Studio::setLocalControlEnabled(bool enabled){
    auto config=object();config.getDynamicObject()->setProperty("schema",1);config.getDynamicObject()->setProperty("enabled",enabled);TemporaryFile tmp(root.getChildFile("data/mcp-settings.json"));if(!tmp.getFile().replaceWithText(JSON::toString(config))||!tmp.overwriteTargetFileWithTemporary())return Result::fail("Could not save local MCP settings.");
    controlMailbox.stop();controlBackupDone=false;auto result=enabled?controlMailbox.start(root):Result::ok();status=result.failed()?result.getErrorMessage():enabled?"Local MCP control enabled for this workspace.":"Local MCP control disabled.";repaint();return result;
}
Result Studio::backupForControl(bool force){
    if(controlBackupDone&&!force)return Result::ok();auto file=root.getChildFile("data/History").getChildFile("before-mcp-"+Time::getCurrentTime().formatted("%Y%m%d-%H%M%S")+"-"+Uuid().toString()+".pulse");auto result=file.getParentDirectory().createDirectory();if(result.wasOk())result=saveProject(absoluteAssets(project,currentFile==File()?root:currentFile.getParentDirectory()),file);if(result.wasOk()){controlBackupDone=true;controlBackupFile=file;}return result;
}
var Studio::controlState()const{
    auto o=object();auto* d=o.getDynamicObject();d->setProperty("version","0.37.0");d->setProperty("revision",(int64)revision);d->setProperty("title",project.title);d->setProperty("bpm",project.bpm);d->setProperty("songMode",project.songMode);d->setProperty("songLengthBeats",project.songLength());d->setProperty("tracks",(int)project.tracks.size());d->setProperty("patterns",(int)project.patterns.size());d->setProperty("clips",(int)project.clips.size());d->setProperty("markers",(int)project.markers.size());d->setProperty("playing",engine->playing.load());d->setProperty("positionBeats",engine->position.load());d->setProperty("framesProcessed",(int64)engine->processedFrames.load());d->setProperty("chasedNotes",(int64)engine->chasedNotes.load());d->setProperty("peakOutput",engine->observedPeak.load());d->setProperty("activeOutputs",activeOutputs.load());d->setProperty("recording",recording);d->setProperty("modalDialog",Component::getCurrentlyModalComponent()!=nullptr);d->setProperty("exporting",exporting.load());d->setProperty("exportProgress",exportProgress.load());d->setProperty("dirty",dirty);d->setProperty("currentFile",currentFile==File()?String():currentFile.getFullPathName());d->setProperty("backup",controlBackupFile==File()?String():controlBackupFile.getFullPathName());d->setProperty("status",status);return o;
}
Result Studio::handleControlCommand(const String& command,const var& args,var& result){
    if(command=="status"){result=controlState();return Result::ok();}
    if(command=="get_project"){result=controlState();result.getDynamicObject()->setProperty("project",projectToJson(absoluteAssets(project,currentFile==File()?root:currentFile.getParentDirectory())));return Result::ok();}
    if(command=="list_sounds"){result=object();Array<var> sounds;for(const auto& p:factorySynthPresets())sounds.add(synthPresetToJson(p));result.getDynamicObject()->setProperty("factorySounds",sounds);result.getDynamicObject()->setProperty("instruments",StringArray{"kick","snare","hat","clap","open_hat","bass","pad","lead","analog","fm","wavetable"}.joinIntoString(", "));return Result::ok();}
    if(command=="snapshot"){auto file=controlMailbox.directory().getChildFile("snapshot-"+Uuid().toString()+".png");if(!controlMailbox.enabled()||!snapshot(file))return Result::fail("Could not capture the live workspace.");result=object();result.getDynamicObject()->setProperty("path",file.getFullPathName());return Result::ok();}
    if(command!="new_song"&&command!="edit"&&command!="transport"&&command!="save_project"&&command!="export_audio"&&command!="undo"&&command!="view")return Result::fail("Unknown local control tool.");
    auto expected=args["expected_revision"];if(!(expected.isInt()||expected.isInt64())||(int64)expected<0||(uint64_t)(int64)expected!=revision)return Result::fail("Project revision changed. Call pulse_status or pulse_get_project before retrying.");
    if(recording||recorder.isActive()||pendingNoteTool()||Component::getCurrentlyModalComponent()||exporting.load())return Result::fail("The app is busy with recording, a note preview, a dialog or an export. Finish it before editing through MCP.");
    if(command=="edit"||command=="new_song"){
        Project candidate;Result valid=Result::ok();if(command=="new_song"){auto setting=object();setting.getDynamicObject()->setProperty("op","set_song");setting.getDynamicObject()->setProperty("title",args["title"]);setting.getDynamicObject()->setProperty("bpm",args["bpm"]);setting.getDynamicObject()->setProperty("songMode",true);setting.getDynamicObject()->setProperty("loop",false);valid=applyControlEdits(emptyProject(),var(Array<var>{setting}),candidate);}else valid=applyControlEdits(project,args["operations"],candidate);if(valid.failed())return valid;
        bool restructuring=false,refreshVoices=false,arrangementChange=false;if(command=="edit")if(auto* operations=args["operations"].getArray())for(const auto& op:*operations){auto kind=op["op"].toString();if(kind=="extract_notes"||kind=="merge_patterns"){restructuring=true;refreshVoices|=!candidate.songMode||(kind=="extract_notes"&&(bool)op["move"]);}if(kind=="section_clips"){arrangementChange=true;refreshVoices|=candidate.songMode;}}
        auto playback=std::make_unique<Playback>();String warnings;valid=compilePlayback(candidate,assets,currentFile==File()?root:currentFile.getParentDirectory(),*playback,warnings);if(valid.failed()||warnings.isNotEmpty())return valid.failed()?valid:Result::fail(warnings);
        if(restructuring&&candidate.songMode){auto patternPreview=candidate;patternPreview.songMode=false;valid=compilePlayback(patternPreview,assets,currentFile==File()?root:currentFile.getParentDirectory(),*playback,warnings);if(valid.failed()||warnings.isNotEmpty())return valid.failed()?valid:Result::fail(warnings);}
        if(arrangementChange&&!candidate.songMode){auto song=candidate;song.songMode=true;valid=compilePlayback(song,assets,currentFile==File()?root:currentFile.getParentDirectory(),*playback,warnings);if(valid.failed()||warnings.isNotEmpty())return valid.failed()?valid:Result::fail(warnings);}
        auto before=JSON::toString(projectToJson(project));if(command=="edit"&&before==JSON::toString(projectToJson(candidate))){result=controlState();return Result::ok();}
        valid=backupForControl(command=="new_song");if(valid.failed())return valid;checkpoint();releaseKeys();if(command=="new_song"){engine->stop();currentFile=File();clipboardHasClip=false;}
        project=std::move(candidate);selectedTrack=jlimit(0,(int)project.tracks.size()-1,selectedTrack);selectedNote=-1;selectedNotes.clear();selectedClip=-1;pianoLow=-1;changed();if(refreshVoices)engine->seekRequested.store(jmin(engine->position.load(),project.songMode?project.songLength():project.patterns[(size_t)project.activePattern].length));status=command=="new_song"?"New song started through local MCP. Previous session is backed up and available in Undo.":"Local MCP edit applied as one undo step.";
    }else if(command=="undo"){if(undoStack.empty())return Result::fail("There are no project edits to undo.");if(activePane==wavePane)activePane=playlistPane;applyHistory(false);}
    else if(command=="transport"){
        auto action=args["action"].toString();if(action=="stop")perform(stop);else if(action=="pause")engine->playing.store(false);else if(action=="play"){if(!audioReady())return Result::fail(status);if(!engine->playing.load())perform(play);}else if(action=="seek"){if(!numeric(args["beat"],0,project.songMode?project.songLength():project.patterns[(size_t)project.activePattern].length))return Result::fail("Seek beat is outside this song or pattern.");engine->seekRequested.store((double)args["beat"]);}else return Result::fail("Choose play, pause, stop or seek.");
    }else if(command=="save_project"||command=="export_audio"){
        if(!safeName(args["name"])||(args.hasProperty("overwrite")&&!args["overwrite"].isBool()))return Result::fail("Choose a name with 1-80 ASCII letters, numbers, spaces, underscores or hyphens.");bool exportingAudio=command=="export_audio";auto target=root.getChildFile(exportingAudio?"Exports":"Projects").getChildFile(args["name"].toString()+(exportingAudio?".wav":".pulse"));if(target.exists()&&!(bool)args["overwrite"])return Result::fail("Destination exists. Choose a new name or explicitly request overwrite.");auto valid=target.getParentDirectory().createDirectory();if(valid.failed())return valid;
        if(!exportingAudio){Project collected;valid=collectAssets(project,currentFile==File()?root:currentFile.getParentDirectory(),target,collected);if(valid.wasOk())valid=saveProject(collected,target);if(valid.failed())return valid;project=std::move(collected);currentFile=target;dirty=false;rememberProject(target);root.getChildFile("data/recovery-v0.29.seen").replaceWithText("current");root.getChildFile("data/recovery-v0.29.pulse").deleteFile();publish();status="Saved local MCP song: "+target.getFileName();}
        else{RenderSettings settings;settings.source=RenderSource::song;settings.normalize=true;settings.targetDb=-1;settings.dither=true;settings.tailSeconds=3;startExport(target,settings);if(!exporting.load())return Result::fail(status);}
        result=controlState();result.getDynamicObject()->setProperty("path",target.getFullPathName());return Result::ok();
    }else if(command=="view"){
        auto view=args["panel"].toString();int pane=view=="playlist"?playlistPane:view=="piano_roll"?pianoPane:view=="mixer"?mixerPane:view=="synth"?synthPane:view=="channel_rack"?rackPane:-1;if(pane<0)return Result::fail("Choose playlist, piano_roll, mixer, synth or channel_rack.");
        if(args.hasProperty("track")&&!numeric(args["track"],0,(double)project.tracks.size()-1,true))return Result::fail("Track is unavailable.");if(args.hasProperty("pattern")&&!numeric(args["pattern"],0,(double)project.patterns.size()-1,true))return Result::fail("Pattern is unavailable.");
        if(args.hasProperty("track"))perform(trackSelect,(int)args["track"]);if(args.hasProperty("pattern")&&(int)args["pattern"]!=project.activePattern)perform(patternSelect,(int)args["pattern"]);if(pane==playlistPane){playlistStart=0;playlistSpan=jmax(16.,project.songLength()+4);trackScroll=0;}showPane(pane);if(!panes[(size_t)pane].maximized)perform(paneMaximize,pane);
    }
    result=controlState();repaint();return Result::ok();
}
}
